INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ovb20-dc-status', 21, 'func', 'Статус дата-центра', 'Напишите функцию dc_statuses(board, up): up — список id хостов в статусе Up. Дата-центр в статусе "Non Responsive", если среди его хостов нет ни одного из up; иначе "Uninitialized", если у него нет главного домена или главный домен не "Active" (правила как в двух предыдущих задачах); иначе "Up". Верните словарь id дата-центра → статус для всех дата-центров доски. Схема доски — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}; у сети может быть ещё "params": {"role": ..., "required": ...}. kind — одно из engine, data_center, cluster, host, network, storage_domain, vm. Связь {"from": id, "to": id} всегда идёт в направлении oVirt: engine → data_center → cluster → host → vm; data_center → network → cluster, host, vm; engine → network; data_center → storage_domain → host, vm. Порядок в списках nodes и edges важен там, где сказано «первый».', 'def dc_statuses(board, up):
    pass
