INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ovb20-spm', 22, 'func', 'Кто SPM', 'Менеджер выбирает SPM среди хостов дата-центра. В нашей модели это первый по порядку в списке nodes хост дата-центра из up, но только если сам дата-центр в статусе "Up" (правила как в предыдущей задаче). Напишите функцию spm_hosts(board, up): верните словарь id дата-центра → id хоста-SPM или None для всех дата-центров доски. Схема доски — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}; у сети может быть ещё "params": {"role": ..., "required": ...}. kind — одно из engine, data_center, cluster, host, network, storage_domain, vm. Связь {"from": id, "to": id} всегда идёт в направлении oVirt: engine → data_center → cluster → host → vm; data_center → network → cluster, host, vm; engine → network; data_center → storage_domain → host, vm. Порядок в списках nodes и edges важен там, где сказано «первый».', 'def spm_hosts(board, up):
    pass
', 'Статус дата-центра уже считали — вынесите это в функцию; затем первый подходящий хост по порядку nodes.', '{"func": "spm_hosts", "tests": [{"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}]}, ["h1", "h2"]], "expected": {"dc1": null}}, {"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h1"}, {"from": "nfs", "to": "h2"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}]}, ["h1", "h2"]], "expected": {"dc1": "h1"}}, {"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h1"}, {"from": "nfs", "to": "h2"}, {"from": "dc1", "to": "scratch"}, {"from": "scratch", "to": "h1"}, {"from": "scratch", "to": "h2"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}, {"id": "scratch", "kind": "storage_domain", "name": "scratch"}]}, ["h1", "h2"]], "expected": {"dc1": "h1"}}, {"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h1"}, {"from": "nfs", "to": "h2"}, {"from": "engine", "to": "dc2"}, {"from": "dc2", "to": "cl2"}, {"from": "cl2", "to": "h3"}, {"from": "dc2", "to": "mgmt2"}, {"from": "mgmt2", "to": "cl2"}, {"from": "engine", "to": "mgmt2"}, {"from": "mgmt2", "to": "h3"}, {"from": "dc2", "to": "nfs2"}, {"from": "nfs2", "to": "h3"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}, {"id": "dc2", "kind": "data_center", "name": "Remote"}, {"id": "cl2", "kind": "cluster", "name": "cluster-b"}, {"id": "h3", "kind": "host", "name": "host-3"}, {"id": "mgmt2", "kind": "network", "name": "ovirtmgmt-2", "params": {"required": true, "role": "management"}}, {"id": "nfs2", "kind": "storage_domain", "name": "nfs-remote"}]}, ["h1", "h2", "h3"]], "expected": {"dc1": "h1", "dc2": "h3"}}, {"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h1"}, {"from": "nfs", "to": "h2"}, {"from": "engine", "to": "dc2"}, {"from": "dc2", "to": "cl2"}, {"from": "cl2", "to": "h3"}, {"from": "dc2", "to": "mgmt2"}, {"from": "mgmt2", "to": "cl2"}, {"from": "engine", "to": "mgmt2"}, {"from": "mgmt2", "to": "h3"}, {"from": "dc2", "to": "nfs2"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}, {"id": "dc2", "kind": "data_center", "name": "Remote"}, {"id": "cl2", "kind": "cluster", "name": "cluster-b"}, {"id": "h3", "kind": "host", "name": "host-3"}, {"id": "mgmt2", "kind": "network", "name": "ovirtmgmt-2", "params": {"required": true, "role": "management"}}, {"id": "nfs2", "kind": "storage_domain", "name": "nfs-remote"}]}, ["h1", "h2"]], "expected": {"dc1": "h1", "dc2": null}}, {"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h1"}, {"from": "nfs", "to": "h2"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}, {"id": "spare", "kind": "storage_domain", "name": "spare"}]}, ["h1", "h2"]], "expected": {"dc1": "h1"}}, {"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h1"}, {"from": "nfs", "to": "h2"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}]}, []], "expected": {"dc1": null}}, {"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h2"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}]}, ["h2"]], "expected": {"dc1": "h2"}}], "board_view": true}');

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 20, 'ovb20-missing-storage', 23, 'func', 'Какого хранилища не хватает хосту', 'Хост становится NonOperational, если не видит домен, подключённый к его дата-центру. Напишите функцию missing_storage(board): для каждого хоста, который входит в кластер дата-центра, верните отсортированный список id доменов, подключённых к дата-центру хоста, но не видимых хосту (нет связи domain → host). В словаре должны быть все такие хосты, в том числе с пустым списком; хосты вне дата-центра в него не входят. Схема доски — словарь {"nodes": [...], "edges": [...]}. Узел: {"id": ..., "kind": ..., "name": ...}; у сети может быть ещё "params": {"role": ..., "required": ...}. kind — одно из engine, data_center, cluster, host, network, storage_domain, vm. Связь {"from": id, "to": id} всегда идёт в направлении oVirt: engine → data_center → cluster → host → vm; data_center → network → cluster, host, vm; engine → network; data_center → storage_domain → host, vm. Порядок в списках nodes и edges важен там, где сказано «первый».', 'def missing_storage(board):
    pass
', 'Дата-центр хоста — через кластер; домены дата-центра — из задачи domains_of.', '{"func": "missing_storage", "tests": [{"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h1"}, {"from": "nfs", "to": "h2"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}]}], "expected": {"h1": [], "h2": []}}, {"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h1"}, {"from": "nfs", "to": "h2"}, {"from": "dc1", "to": "scratch"}, {"from": "scratch", "to": "h1"}, {"from": "scratch", "to": "h2"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}, {"id": "scratch", "kind": "storage_domain", "name": "scratch"}]}], "expected": {"h1"