quired": true, "role": "management"}}, {"id": "vmnet", "kind": "network", "name": "vm-net", "params": {"required": true, "role": "vm"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}, {"id": "vm1", "kind": "vm", "name": "web-1"}]}], "expected": {"h1": [], "h2": [], "h3": []}}, {"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h1"}, {"from": "nfs", "to": "h2"}, {"from": "nfs", "to": "h9"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "storage_domain", "name": "nfs-data"}, {"id": "h9", "kind": "host", "name": "host-9"}]}], "expected": {"h1": [], "h2": []}}, {"args": [{"edges": [{"from": "engine", "to": "dc1"}, {"from": "dc1", "to": "cl1"}, {"from": "cl1", "to": "h1"}, {"from": "cl1", "to": "h2"}, {"from": "dc1", "to": "mgmt"}, {"from": "mgmt", "to": "cl1"}, {"from": "engine", "to": "mgmt"}, {"from": "mgmt", "to": "h1"}, {"from": "mgmt", "to": "h2"}, {"from": "dc1", "to": "nfs"}, {"from": "nfs", "to": "h2"}], "nodes": [{"id": "engine", "kind": "engine", "name": "engine"}, {"id": "dc1", "kind": "data_center", "name": "Default"}, {"id": "cl1", "kind": "cluster", "name": "cluster-a"}, {"id": "h1", "kind": "host", "name": "host-1"}, {"id": "h2", "kind": "host", "name": "host-2"}, {"id": "mgmt", "kind": "network", "name": "ovirtmgmt", "params": {"required": true, "role": "management"}}, {"id": "nfs", "kind": "stor